const fs = require('fs');
const buf = fs.readFileSync('/workspace/world.db');
// Search for ORD-CCC96C in the raw binary
const str = buf.toString('utf8');
const idx = str.indexOf('ORD-CCC96C');
if (idx >= 0) {
  // Print surrounding context
  const start = Math.max(0, idx - 200);
  const end = Math.min(str.length, idx + 500);
  const context = buf.slice(start, end).toString('utf8').replace(/[^\x20-\x7E\n\r\t]/g, ' ');
  console.log(context);
}
"

