NODE_PATH=/tmp/node_modules node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// 1. Cancel the Aurora Smart Desk Lamp Pro item
db.prepare(\`
  UPDATE order_items
  SET item_status = 'cancelled'
  WHERE order_id = 'ORD-CCC96C' AND oi_id = 'ITEM-59FB3E'
\`).run();

// 2. Record the refund transaction
db.prepare(\`
  INSERT INTO order_payments (order_id, transaction_type, amount, payment_method_id, created_at)
  VALUES ('ORD-CCC96C', 'refund', 88.00, 'credit_card', datetime('now'))
\`).run();

// 3. Verify the changes
const item = db.prepare('SELECT oi_id, name, unit_price, item_status FROM order_items WHERE order_id = ? AND oi_id = ?').get('ORD-CCC96C', 'ITEM-59FB3E');
console.log('Updated item:', JSON.stringify(item));

const allItems = db.prepare('SELECT oi_id, name, quantity, unit_price, item_status FROM order_items WHERE order_id = ?').all('ORD-CCC96C');
console.log('All items:', JSON.stringify(allItems, null, 2));

const payments = db.prepare('SELECT * FROM order_payments WHERE order_id = ?').all('ORD-CCC96C');
console.log('Payments:', JSON.stringify(payments, null, 2));
"

